# apply_calibration_and_run.py — adds 2 new files, then runs the fully calibrated
# GBM (train->val->test) and prints deltas vs the previous uncalibrated run.
import base64, sys, pathlib, subprocess

FILES = {
    'src/models/calibrate.py': '',
    'src/eval/backtest_gbm_calibrated.py': '',
}


def main():
    # scikit-learn needed for isotonic
    try:
        import sklearn  # noqa: F401
    except ImportError:
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "scikit-learn"], check=True)

    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    import pandas as pd
    from src.eval.backtest_gbm_calibrated import backtest_gbm_calibrated, summarize_test

    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")

    print("\nRunning calibrated pipeline: train=2022, val=2023, test=2024-2026")
    out = backtest_gbm_calibrated(
        races, entries, sessions,
        train_end="2023-01-01",
        val_end="2024-01-01",
    )

    print("\n=== TEST — T only (no isotonic) ===")
    print(summarize_test(out["test_metrics"]).round(4).to_string())

    print("\n=== TEST — T + isotonic winner calibration ===")
    print(summarize_test(out["test_metrics_iso"]).round(4).to_string())

if __name__ == "__main__":
    main()
